    m=[]; pri=[]
    for c in [0,1]:
        Xc=Xtr[ytr==c]; m.append(Xc.mean(0)); pri.append(len(Xc)/len(Xtr))
    m=np.array(m); pri=np.array(pri)
    cov=np.cov(Xtr,rowvar=False,bias=True)+reg*np.eye(Xtr.shape[1])
    inv=np.linalg.pinv(cov)
    s=[]
