        mc=m[c]
        s.append(Xva@inv@mc -0.5*(mc@inv@mc)+np.log(pri[c]))
    return (s[1]>s[0]).astype(int)

def logistic(Xtr,ytr,Xva,l2=1.0,steps=600,lr=0.2):
    n,p=Xtr.shape; w=np.zeros(p); b=0.0
    for _ in range(steps):
